//! `POST /v1/completions`: each prompt, as text or tokens, generated by the model's text engine; several prompts run at once, as choices.

use std::sync::Arc;

use axum::{
    Json,
    extract::State,
    http::HeaderMap,
    response::{IntoResponse, Response},
};
use futures::future::{join_all, try_join_all};

use crate::{
    api::{
        Stop, Usage,
        completion::{Completion, CompletionChoice, CompletionRequest, PromptInput},
        now, warn_unknown,
    },
    error::{ApiError, ApiResult},
    generation::output::{Piece, TextGeneration},
    handler::{ApiJson, blocking, max_tokens, request_id, stream::stream},
    registry::Served,
    text::Detokenizer,
};

const ENDPOINT: &str = "/v1/completions";

/// Serves `POST /v1/completions`: generates a completion of each prompt, at most 16 tokens unless `max_tokens` says otherwise, as one choice each, or as server-sent chunks ending in `data: [DONE]` when `stream` is set.
/// A client that leaves a stream cancels its requests on the engine.
///
/// # Errors
///
/// Returns a 404 error for an unknown model, 422 for a model that does not generate text, 400 for no prompts, a token outside the vocabulary, an invalid field or token limit, or a field it does not support, 429 when the engine's queue is full, and 503 while the model loads.
/// A stream that fails after it starts ends with the error as its last event.
pub async fn create(
    State(served): State<Served>,
    headers: HeaderMap,
    ApiJson(request): ApiJson<CompletionRequest>,
) -> ApiResult<Response> {
    warn_unknown(ENDPOINT, &request.unknown);
    let model = served.get(&request.model)?;
    let (engine, format) = model.text(ENDPOINT)?;
    let fields = &request.generation;
    fields.check_supported()?;
    if request.echo {
        return Err(ApiError::unsupported_field("echo"));
    }

    if request
        .suffix
        .as_ref()
        .is_some_and(|suffix| !suffix.is_empty())
    {
        return Err(ApiError::unsupported_field("suffix"));
    }

    if request.best_of.is_some_and(|best_of| best_of != 1) {
        return Err(ApiError::unsupported_field("best_of"));
    }

    if request.logprobs.is_some() {
        return Err(ApiError::unsupported_field("logprobs"));
    }

    let inputs = request.prompt.clone().inputs();
    if inputs.is_empty() {
        return Err(ApiError::invalid_field("prompt", "no prompts"));
    }

    let encoding = Arc::clone(format);
    let prompts = blocking(move || {
        let vocabulary = encoding.tokenizer.vocabulary_size();
        inputs
            .into_iter()
            .map(|input| match input {
                PromptInput::Text(text) => encoding.encode(&text, true),
                PromptInput::Tokens(tokens) => {
                    if let Some(&token) = tokens
                        .iter()
                        .find(|&&token| token < 0 || token >= vocabulary)
                    {
                        return Err(ApiError::invalid_field(
                            "prompt",
                            format!("token {token} outside a vocabulary of {vocabulary}"),
                        ));
                    }
                    Ok(tokens)
                }
            })
            .collect::<ApiResult<Vec<_>>>()
    })
    .await?;

    let mut generations = Vec::with_capacity(prompts.len());
    let mut prompt_tokens = Vec::with_capacity(prompts.len());
    for prompt in prompts {
        let limit = max_tokens(
            fields.max_tokens.or(Some(16)),
            prompt.len(),
            engine.limits(),
        )?;
        let options = format.sequence(
            limit,
            fields.sampling(),
            &fields.stop_token_ids,
            fields.ignore_eos,
        )?;
        let stop_tokens = options.stop_tokens.clone();
        prompt_tokens.push(prompt.len());
        let detokenizer = Detokenizer::new(
            Arc::clone(&format.tokenizer),
            fields.skip_special_tokens.unwrap_or(true),
            &prompt,
        )?;
        generations.push(TextGeneration::new(
            engine.submit(prompt, options)?,
            detokenizer,
            request
                .generation
                .stop
                .as_ref()
                .map_or_else(Vec::new, |stop| Stop::strings(Some(stop))),
            stop_tokens,
        ));
    }

    let id = format!("cmpl-{}", request_id(&headers));
    let created = now();
    let name = model.name.clone();

    if !fields.stream {
        let finished = try_join_all(generations.iter_mut().map(TextGeneration::collect)).await?;
        let completion_tokens = generations
            .iter()
            .zip(&prompt_tokens)
            .map(|(generation, &prompt)| {
                generation.log(&name, prompt);
                generation.tokens().len()
            })
            .sum();
        let choices = finished
            .into_iter()
            .enumerate()
            .map(|(index, (text, reason))| CompletionChoice {
                index,
                text,
                finish_reason: Some(reason.as_str()),
                logprobs: None,
            })
            .collect();
        return Ok(Json(Completion {
            id,
            object: "text_completion",
            created,
            model: name,
            choices,
            usage: Some(Usage::new(prompt_tokens.iter().sum(), completion_tokens)),
        })
        .into_response());
    }

    let include_usage = fields.include_usage();
    Ok(stream(move |events| async move {
        let chunk = |index: usize, text: String, finish_reason: Option<&'static str>| Completion {
            id: id.clone(),
            object: "text_completion",
            created,
            model: name.clone(),
            choices: vec![CompletionChoice {
                index,
                text,
                finish_reason,
                logprobs: None,
            }],
            usage: None,
        };
        let streams = generations
            .iter_mut()
            .enumerate()
            .map(|(index, generation)| {
                let events = events.clone();
                let chunk = &chunk;
                async move {
                    loop {
                        let sent = match generation.next().await {
                            Ok(Some(Piece::Text(text))) => {
                                events.json(&chunk(index, text, None)).await
                            }
                            Ok(Some(Piece::Finished(reason))) => {
                                events
                                    .json(&chunk(index, String::new(), Some(reason.as_str())))
                                    .await
                            }
                            Ok(None) => return true,
                            Err(error) => {
                                events.error(&error).await;
                                return false;
                            }
                        };
                        if !sent {
                            return false;
                        }
                    }
                }
            });
        if !join_all(streams).await.into_iter().all(|finished| finished) {
            return;
        }

        let completion_tokens = generations
            .iter()
            .zip(&prompt_tokens)
            .map(|(generation, &prompt)| {
                generation.log(&name, prompt);
                generation.tokens().len()
            })
            .sum();
        if include_usage {
            let usage = Completion {
                id: id.clone(),
                object: "text_completion",
                created,
                model: name.clone(),
                choices: Vec::new(),
                usage: Some(Usage::new(prompt_tokens.iter().sum(), completion_tokens)),
            };
            if !events.json(&usage).await {
                return;
            }
        }

        events.done().await;
    }))
}
